type Item struct {
	ID   int       `json:"id"`
	Name string    `json:"name"`
}

type Store struct {
	mu     sync.Mutex
	nextID int
	items  map[int]Item
}

func NewStore() *Store {
	return &Store{
		nextID: 1,
		items:  make(map[int]Item),
	}
}

func (s *Store) Create(name string) Item {
	s.mu.Lock()
	defer s.mu.Unlock()
	item := Item{ID: s.nextID, Name: name}
	s.items[item.ID] = item
	s.nextID++
	return item
}

func (s *Store) List() []Item {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]Item, 0, len(s.items))
	for _, it := range s.items {
		out = append(out, it)
	}
	return out
}
